/// The bundled asset path for a `(style, seed)` pair, or `None` if that pair
/// is not in the bundled set — which happens for an unchosen avatar (empty
/// seed), a settings file edited by hand, or a style removed from a later
/// build. Callers fall back to rendering an initial.
pub fn asset_path(style: &str, seed: &str) -> Option<&'static str> {
    STYLES
        .iter()
        .find(|s| s.id == style)?
        .variants
        .iter()
        .find(|(variant, _)| *variant == seed)
        .map(|(_, path)| *path)
}

/// Looks up a style by id, for showing its label.
pub fn style(id: &str) -> Option<&'static AvatarStyle> {
    STYLES.iter().find(|s| s.id == id)
}

